import{_ as l,W as i,s as o,u as d,I as e,ah as u,w as a,Z as n,A as p}from"./chunks/framework.DYeiaKBS.js";import"./chunks/theme.DJBbXXYU.js";const C=JSON.parse('{"title":"创建局域网内的离线 Yum 仓库 | LCTT x X-CMD","titleTemplate":false,"description":"创建局域网内的离线 Yum 仓库 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"创建局域网内的离线 Yum 仓库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"创建局域网内的离线 Yum 仓库 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180103 Creating an Offline YUM repository for LAN","title":"创建局域网内的离线 Yum 仓库","tag":"201802"},"relativePath":"201802/20180103 Creating an Offline YUM repository for LAN.md","filePath":"[post].md"}'),r={name:"201802/20180103 Creating an Offline YUM repository for LAN.md"};function m(h,s,b,c,g,f){const t=i("Link");return d(),o("div",null,[s[22]||(s[22]=e("h1",{id:"创建局域网内的离线-yum-仓库",tabindex:"-1"},[a("创建局域网内的离线 Yum 仓库 "),e("a",{class:"header-anchor",href:"#创建局域网内的离线-yum-仓库","aria-label":"Permalink to 创建局域网内的离线 Yum 仓库"},"​")],-1)),e("p",null,[s[1]||(s[1]=a("在早先的教程中，我们讨论了")),n(t,{href:"https://linux.cn/article-9296-1.html"},{default:p(()=>s[0]||(s[0]=[a("如何使用 ISO 镜像和在线 Yum 仓库的方式来创建自己的 Yum 仓库 ")])),_:1}),s[2]||(s[2]=a("。创建自己的 Yum 仓库是一个不错的想法，但若网络中只有 2-3 台 Linux 机器那就没啥必要了。不过若你的网络中有大量的 Linux 服务器，而且这些服务器还需要定时进行升级，或者你有大量服务器无法直接访问互联网，那么创建自己的 Yum 仓库就很有必要了。"))]),s[23]||(s[23]=e("p",null,"当我们有大量的 Linux 服务器，而每个服务器都直接从互联网上升级系统时，数据消耗会很可观。为了节省数据量，我们可以创建个离线 Yum 源并将之分享到本地网络中。网络中的其他 Linux 机器就可以直接从本地 Yum 上获取系统更新，从而节省数据量，而且传输速度也会很好。",-1)),s[24]||(s[24]=e("p",null,"我们可以使用下面两种方法来分享 Yum 仓库：",-1)),s[25]||(s[25]=e("ul",null,[e("li",null,"使用 Web 服务器（Apache）"),e("li",null,"使用 FTP 服务器（VSFTPD）")],-1)),e("p",null,[s[4]||(s[4]=a("在开始讲解这两个方法之前，我们需要先根据")),n(t,{href:"https://linux.cn/article-9296-1.html"},{default:p(()=>s[3]||(s[3]=[a("之前的教程")])),_:1}),s[5]||(s[5]=a("创建一个 Yum 仓库。"))]),s[26]||(s[26]=u(`<h3 id="使用-web-服务器" tabindex="-1">使用 Web 服务器 <a class="header-anchor" href="#使用-web-服务器" aria-label="Permalink to 使用 Web 服务器">​</a></h3><p>首先在 Yum 服务器上安装 Web 服务器（Apache），我们假设服务器 IP 是 <code>192.168.1.100</code>。我们已经在这台系统上配置好了 Yum 仓库，现在我们来使用 <code>yum</code> 命令安装 Apache Web 服务器，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ yum install httpd</span></span></code></pre></div><p>下一步，拷贝所有的 rpm 包到默认的 Apache 根目录下，即 <code>/var/www/html</code>，由于我们已经将包都拷贝到了 <code>/YUM</code> 下，我们也可以创建一个软连接来从 <code>/var/www/html</code> 指向 <code>/YUM</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ln -s /var/www/html/Centos /YUM</span></span></code></pre></div><p>重启 Web 服务器应用改变：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ systemctl restart httpd</span></span></code></pre></div><h4 id="配置客户端机器" tabindex="-1">配置客户端机器 <a class="header-anchor" href="#配置客户端机器" aria-label="Permalink to 配置客户端机器">​</a></h4><p>服务端的配置就完成了，现在需要配置下客户端来从我们创建的离线 Yum 中获取升级包，这里假设客户端 IP 为 <code>192.168.1.101</code>。</p><p>在 <code>/etc/yum.repos.d</code> 目录中创建 <code>offline-yum.repo</code> 文件，输入如下信息，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vi /etc/yum.repos.d/offline-yum.repo</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name=Local YUM</span></span>
<span class="line"><span>baseurl=http://192.168.1.100/CentOS/7</span></span>
<span class="line"><span>gpgcheck=0</span></span>
<span class="line"><span>enabled=1</span></span></code></pre></div><p>客户端也配置完了。试一下用 <code>yum</code> 来安装/升级软件包来确认仓库是正常工作的。</p><h3 id="使用-ftp-服务器" tabindex="-1">使用 FTP 服务器 <a class="header-anchor" href="#使用-ftp-服务器" aria-label="Permalink to 使用 FTP 服务器">​</a></h3><p>在 FTP 上分享 Yum，首先需要安装所需要的软件包，即 vsftpd。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ yum install vsftpd</span></span></code></pre></div><p>vsftp 的默认根目录为 <code>/var/ftp/pub</code>，因此你可以拷贝 rpm 包到这个目录，或者为它创建一个软连接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ln -s /var/ftp/pub /YUM</span></span></code></pre></div><p>重启服务应用改变：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ systemctl restart vsftpd</span></span></code></pre></div><h4 id="配置客户端机器-1" tabindex="-1">配置客户端机器 <a class="header-anchor" href="#配置客户端机器-1" aria-label="Permalink to 配置客户端机器">​</a></h4><p>像上面一样，在 <code>/etc/yum.repos.d</code> 中创建 <code>offline-yum.repo</code> 文件，并输入下面信息，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vi /etc/yum.repos.d/offline-yum.repo</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Offline YUM]</span></span>
<span class="line"><span>name=Local YUM</span></span>
<span class="line"><span>baseurl=ftp://192.168.1.100/pub/CentOS/7</span></span>
<span class="line"><span>gpgcheck=0</span></span>
<span class="line"><span>enabled=1</span></span></code></pre></div>`,24)),e("p",null,[s[7]||(s[7]=a("现在客户机可以通过 ftp 接收升级了。要配置 vsftpd 服务器为其他 Linux 系统分享文件，请")),n(t,{href:"http://linuxtechlab.com/ftp-secure-installation-configuration/"},{default:p(()=>s[6]||(s[6]=[a("阅读这篇指南")])),_:1}),s[8]||(s[8]=a("。"))]),s[27]||(s[27]=e("p",null,"这两种方法都很不错，你可以任意选择其中一种方法。有任何疑问或这想说的话，欢迎在下面留言框中留言。",-1)),s[28]||(s[28]=e("hr",null,null,-1)),e("p",null,[s[10]||(s[10]=a("via: ")),n(t,{href:"http://linuxtechlab.com/offline-yum-repository-for-lan/"},{default:p(()=>s[9]||(s[9]=[a("http://linuxtechlab.com/offline-yum-repository-for-lan/")])),_:1})]),e("p",null,[s[14]||(s[14]=a("作者：")),n(t,{href:"http://linuxtechlab.com/author/shsuain/"},{default:p(()=>s[11]||(s[11]=[a("Shusain")])),_:1}),s[15]||(s[15]=a(" 译者：")),n(t,{href:"https://github.com/lujun9972"},{default:p(()=>s[12]||(s[12]=[a("lujun9972")])),_:1}),s[16]||(s[16]=a(" 校对：")),n(t,{href:"https://github.com/wxy"},{default:p(()=>s[13]||(s[13]=[a("wxy")])),_:1})]),e("p",null,[s[19]||(s[19]=a("本文由 ")),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>s[17]||(s[17]=[a("LCTT")])),_:1}),s[20]||(s[20]=a(" 原创编译，")),n(t,{href:"https://linux.cn/"},{default:p(()=>s[18]||(s[18]=[a("Linux中国")])),_:1}),s[21]||(s[21]=a(" 荣誉推出"))])])}const k=l(r,[["render",m]]);export{C as __pageData,k as default};
